def f(a: int, b: int) -> int:
    """Returns the count of distinct prime factors of min(a,b) if a != b, else 0."""
    if a == b:
        return 0
    n = min(a, b)
    if n == 0:
        return 0
    count = 0
    # Check for divisibility by 2
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2
    # Check for odd divisors up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i
        i += 2
    if n > 1:
        count += 1
    return count
```

